using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyTierPricing;

public class LoyaltyTierPricingAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_price_of_their_loyalty_tier()
    {
        // Returning customer is charged the price of their loyalty tier (Bronze)
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
E
